-- Migration: 005_striver_a2z_sheet.sql
-- Replaces the 23-day starter curriculum with Striver's A2Z DSA Sheet
-- (455 problems, 18 steps), sourced from
-- https://codolio.com/question-tracker/sheet/strivers-a2z-dsa-sheet
--
-- day_number now holds the A2Z step (1-18); sub_topic is the lecture
-- within a step and position is the sheet's global order. Codolio's "Basic"
-- difficulty is stored as Easy to fit the existing check constraint.
-- Re-runnable: rows are upserted on (day_number, title), so progress survives.

ALTER TABLE dsa_problems ALTER COLUMN topic TYPE VARCHAR(150);
ALTER TABLE dsa_problems ADD COLUMN IF NOT EXISTS sub_topic VARCHAR(150);
ALTER TABLE dsa_problems ADD COLUMN IF NOT EXISTS position INTEGER;
ALTER TABLE dsa_problems ADD COLUMN IF NOT EXISTS resource_url TEXT;

-- Drop the old starter set (and its progress rows, via ON DELETE CASCADE).
DELETE FROM dsa_problems WHERE sub_topic IS NULL;

ON CONFLICT (day_number, title) DO UPDATE SET
  topic = EXCLUDED.topic,
  sub_topic = EXCLUDED.sub_topic,
  position = EXCLUDED.position,
  difficulty = EXCLUDED.difficulty,
  url = EXCLUDED.url,
  resource_url = EXCLUDED.resource_url;
